import { useState } from "react";

export function ClickDemo({
  label = "{{label}}",
  variant = "{{variant}}",
  accent = "{{accent}}",
  showPressed = {{showPressed}},
  radius = {{radius}},
}) {
  const [pressed, setPressed] = useState(showPressed);
  const skin = {
    primary: { background: accent, color: "#FAF7F2" },
    secondary: { background: "transparent", color: accent },
    ghost: { background: "transparent", borderColor: "transparent", color: accent },
  }[variant];
  return (
    <div style={{ width: 300, fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430" }}>
      <button type="button" className="click-btn"
        onMouseDown={() => setPressed(true)}
        onMouseUp={() => setPressed(false)}
        style={{ padding: "12px 22px", border: "2px solid " + accent, fontWeight: 600, cursor: "pointer",
          transform: pressed ? "scale(.96)" : "none", filter: pressed ? "brightness(.9)" : "none",
          borderRadius: radius, ...skin }}>{label}</button>
      <p style={{ marginTop: 10, fontSize: 12, color: "#241430aa" }}>{pressed ? "shown mid-click: scaled down, darker" : "rest state \u2014 try clicking it"}</p>
      <style>{`
        @media (prefers-reduced-motion: no-preference) {
          .click-btn { transition: transform .08s; }
        }
      `}</style>
    </div>
  );
}
